s=s[:nav_i]+nav+s[nav_j:]
s=s.replace('family=Aref+Ruqaa:wght@400;700&','family=Aref+Ruqaa:wght@400;700&family=Lalezar&',1)
s=s.replace("d+=1;return h;","d+=.42;return h;",1).replace("(d+.45).toFixed(2)","(d+.17).toFixed(2)",1).replace("let d=0.15;","let d=0.05;",1)
